  const lum = 0.85 + Math.sin(reaction * Math.PI) * 0.3;
  const edge = Math.abs(reaction) > 0.6 ? 1.3 : 1.0;
  const neon = inBar || primeTick > 0 ? 1.4 : 1.0;
  const m = lum * edge * neon;
  return [
    Math.min(255, (pal[i][0] + (pal[i+1][0] - pal[i][0]) * f) * m) | 0,
    Math.min(255, (pal[i][1] + (pal[i+1][1] - pal[i][1]) * f) * m) | 0,
    Math.min(255, (pal[i][2] + (pal[i+1][2] - pal[i][2]) * f) * m) | 0
  ];
}
